exercises.solution:
use std::sync::atomic::{AtomicU32, Ordering};

pub static HITS: AtomicU32 = AtomicU32::new(0);

pub fn hit() -> u32 {
    HITS.fetch_add(1, Ordering::Relaxed) + 1
}

pub fn hits() -> u32 {
    HITS.load(Ordering::Relaxed)
}

pub fn run() -> u32 {
    hit();
    hit();
    hit()
}
